sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
# id: threats_to_validity_over_time
# Return paper, year, and threat type label reported (one row per reported threat type)
SELECT ?paper ?year ?threat_label WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C27001 .
  ?paper orkgp:P29 ?year .
  ?contribution orkgp:P135046 ?venue .
  ?venue rdfs:label ?venue_name .
  FILTER(LCASE(STR(?venue_name)) = LCASE("IEEE International Requirements Engineering Conference"))
  ?contribution orkgp:P39099 ?tv .
  { ?tv orkgp:P55034 ?o . BIND("external validity" AS ?threat_label) }
  UNION { ?tv orkgp:P55035 ?o . BIND("internal validity" AS ?threat_label) }
  UNION { ?tv orkgp:P55036 ?o . BIND("conclusion validity" AS ?threat_label) }
  UNION { ?tv orkgp:P55037 ?o . BIND("construct validity" AS ?threat_label) }
  UNION { ?tv orkgp:P59109 ?o . BIND("reliability" AS ?threat_label) }
  UNION { ?tv orkgp:P60006 ?o . BIND("generalizability" AS ?threat_label) }
  UNION { ?tv orkgp:P97002 ?o . BIND("repeatability" AS ?threat_label) }
  UNION { ?tv orkgp:P68005 ?o . BIND("content validity" AS ?threat_label) }
  UNION { ?tv orkgp:P97000 ?o . BIND("descriptive validity" AS ?threat_label) }
  UNION { ?tv orkgp:P97001 ?o . BIND("theoretical validity" AS ?threat_label) }
  UNION { ?tv orkgp:P145000 ?o . BIND("mentioned" AS ?threat_label) }
}
ORDER BY ?year ?threat_label

